INSERT INTO auth_governance.projection_stream(fence_id,policy_id)
SELECT id,id FROM auth_governance.policy_partition WHERE id=#{t.fenceId} AND tenant_id=#{t.partition.tenantId} AND application_id=#{t.partition.applicationId} AND environment=#{t.partition.environment}

INSERT INTO auth_governance.projection_stream(fence_id,directory_id)
SELECT id,id FROM auth_governance.directory_fence WHERE id=#{t.fenceId} AND tenant_id=#{t.partition.tenantId}
 ON CONFLICT DO NOTHING

mapper.select:
SELECT id,version,membership_id,generation,(state IN ('PENDING','ACTIVE') AND valid_to >clock_timestamp()) AS present,group_id
FROM auth_governance.access_grant WHERE tenant_id=#{t.partition.tenantId} AND application_id=#{t.partition.applicationId}
AND environment=#{t.partition.environment} AND id > #{after} ORDER BY id LIMIT 51

mapper.update:
UPDATE auth_governance.projection_stream SET marker=#{o.id},zed_token=#{token},confirmed_batch=#{o.batchNo},
 target_epoch=#{o.targetEpoch},scan_cursor=#{o.afterCursor},failures=0,next_attempt_at=clock_timestamp(),updated_at=clock_timestamp()
 WHERE fence_id=#{o.fenceId} AND confirmed_batch < #{o.batchNo} AND marker IS NOT DISTINCT FROM #{o.expectedMarker}
